import httpx
from fastmcp import Server
from typing import Any, Dict

def create_openapi_mcp_server(
    openapi_spec: Dict[str, Any], client: httpx.AsyncClient
) -> Server:
    """
    Create an MCP server with tools that mirror an OpenAPI 3.0 specification.

    Args:
        openapi_spec: OpenAPI 3.0 spec as a Python dict
        client: httpx.AsyncClient configured with base URL

    Returns:
        Configured fastmcp Server instance
    """
    server = Server("openapi-mcp-server")

    paths = openapi_spec.get("paths", {})

    for path, path_item in paths.items():
        for method_name, operation in path_item.items():
            if not isinstance(operation, dict) or method_name.startswith("x-"):
                continue
            if method_name.lower() not in ["get", "post", "put", "delete", "patch", "head", "options"]:
                continue

            operation_id = operation.get(
                "operationId",
                f"{method_name}_{path.replace('/', '_').replace('{', '').replace('}', '')}"
            )
            summary = operation.get("summary", "")
            description = operation.get("description", "")

            parameters = operation.get("parameters", [])
            request_body = operation.get("requestBody")

            properties = {}
            required_fields = []

            for param in parameters:
                param_name = param["name"]
                param_schema = param.get("schema", {"type": "string"})
                properties[param_name] = param_schema
                if param.get("required", False):
                    required_fields.append(param_name)

            if request_body:
                content = request_body.get("content", {})
                json_schema = content.get("application/json", {}).get("schema", {})
                if json_schema:
                    properties["_request_body"] = json_schema
                    if request_body.get("required", False):
                        required_fields.append("_request_body")

            def make_tool_function(op_path, op_method, op_params):
                async def tool_impl(**kwargs) -> Dict[str, Any]:
                    url = op_path
                    query_params = {}
                    headers = {}

                    for param in op_params:
                        param_name = param["name"]
                        if param_name not in kwargs:
                            continue

                        value = kwargs[param_name]
                        param_in = param.get("in", "query")

                        if param_in == "path":
                            url = url.replace(f"{{{param_name}}}", str(value))
                        elif param_in == "query":
                            query_params[param_name] = value
                        elif param_in == "header":
                            headers[param_name] = value

                    request_kwargs = {}
                    if query_params:
                        request_kwargs["params"] = query_params
                    if headers:
                        request_kwargs["headers"] = headers
                    if "_request_body" in kwargs:
                        request_kwargs["json"] = kwargs["_request_body"]

                    response = await client.request(
                        op_method.upper(), url, **request_kwargs
                    )
                    response.raise_for_status()

                    if response.text:
                        return response.json()
                    return {}

                return tool_impl

            tool_function = make_tool_function(path, method_name, parameters)
            tool_description = f"{summary}\n{description}".strip() if summary or description else operation_id

            server.add_tool(
                tool_function,
                name=operation_id,
                description=tool_description,
                schema={
                    "type": "object",
                    "properties": properties,
                    "required": required_fields,
                },
            )

    return server

